import{_ as t,o,c as a,a1 as l}from"./chunks/framework.DdbKPUhY.js";const p=JSON.parse('{"title":"Allocator Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/allocator.md","filePath":"spec/allocator.md"}'),r={name:"spec/allocator.md"};function i(n,e,s,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="allocator-spec" tabindex="-1">Allocator Spec <a class="header-anchor" href="#allocator-spec" aria-label="Permalink to &quot;Allocator Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Allocator module provides a unified memory allocation interface. The allocation backend is selected at compile time.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-alloc" tabindex="-1">uvhttp_alloc <a class="header-anchor" href="#uvhttp-alloc" aria-label="Permalink to &quot;uvhttp_alloc&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void* uvhttp_alloc(size_t size)</code></li><li><strong>Purpose</strong>: Allocate memory</li><li><strong>Preconditions</strong>: <code>size</code> &gt; 0</li><li><strong>Returns</strong>: Pointer to allocated memory, or NULL on failure.</li><li><strong>Thread safety</strong>: Depends on backend (system allocator is thread-safe).</li></ul><h3 id="uvhttp-free" tabindex="-1">uvhttp_free <a class="header-anchor" href="#uvhttp-free" aria-label="Permalink to &quot;uvhttp_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_free(void* ptr)</code></li><li><strong>Purpose</strong>: Free allocated memory</li><li><strong>Preconditions</strong>: <code>ptr</code> must be from <code>uvhttp_alloc</code>, <code>uvhttp_calloc</code>, or <code>uvhttp_realloc</code>. Can be NULL (no-op).</li><li><strong>Thread safety</strong>: Depends on backend.</li></ul><h3 id="uvhttp-realloc" tabindex="-1">uvhttp_realloc <a class="header-anchor" href="#uvhttp-realloc" aria-label="Permalink to &quot;uvhttp_realloc&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void* uvhttp_realloc(void* ptr, size_t size)</code></li><li><strong>Purpose</strong>: Reallocate memory</li><li><strong>Preconditions</strong>: <code>ptr</code> must be from a previous allocation. Can be NULL (equivalent to alloc).</li><li><strong>Returns</strong>: Pointer to reallocated memory, or NULL on failure.</li><li><strong>Thread safety</strong>: Depends on backend.</li></ul><h3 id="uvhttp-calloc" tabindex="-1">uvhttp_calloc <a class="header-anchor" href="#uvhttp-calloc" aria-label="Permalink to &quot;uvhttp_calloc&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void* uvhttp_calloc(size_t nmemb, size_t size)</code></li><li><strong>Purpose</strong>: Allocate and zero-initialize memory</li><li><strong>Preconditions</strong>: <code>nmemb * size</code> &gt; 0</li><li><strong>Returns</strong>: Pointer to zero-initialized memory, or NULL on failure.</li><li><strong>Thread safety</strong>: Depends on backend.</li></ul><h3 id="uvhttp-allocator-name" tabindex="-1">uvhttp_allocator_name <a class="header-anchor" href="#uvhttp-allocator-name" aria-label="Permalink to &quot;uvhttp_allocator_name&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_allocator_name(void)</code></li><li><strong>Purpose</strong>: Get the name of the current allocator backend</li><li><strong>Returns</strong>: &quot;system&quot;, &quot;mimalloc&quot;, or &quot;custom&quot;.</li><li><strong>Thread safety</strong>: Thread-safe.</li></ul><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to &quot;Backends&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td>System</td><td>0</td><td>Standard <code>malloc</code>/<code>free</code></td></tr><tr><td>mimalloc</td><td>1</td><td>Microsoft mimalloc</td></tr><tr><td>Custom</td><td>2</td><td>User-provided allocator</td></tr></tbody></table><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Rule 1</strong>: Never mix allocators. Memory allocated with <code>uvhttp_alloc</code> must be freed with <code>uvhttp_free</code>.</p></li><li><p><strong>Rule 2</strong>: Always check allocation results. NULL means out of memory.</p></li><li><p><strong>Rule 3</strong>: Every allocation must have a matching free. No leaks.</p></li><li><p><strong>Rule 4</strong>: NULL can be passed to <code>uvhttp_free</code> safely (no-op).</p></li></ol><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Basic allocation and free</li><li>Zero-size allocation</li><li>Large allocation</li><li>Reallocation</li><li>Calloc zero-initialization</li><li>NULL free (no-op)</li><li>Allocator name retrieval</li><li>No leaks under ASan</li></ul>',20)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
